#!/usr/bin/env python3
"""Deepen the Longqing transition, northern defence and tribute markets."""
from __future__ import annotations
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'App/Resources/history.json'
NARRATION=ROOT/'App/Resources/narration_manifest.json'

def upsert(items,item,key='id'):
    for i,old in enumerate(items):
        if old.get(key)==item[key]: items[i]=item; return
    items.append(item)

def sec(i,title,text,sources,events,people):
    return {'id':i,'title':title,'text':text,'kind':'史实与解读','sources':sources,'events':events,'people':people}

def article(person,title,dek,sections):
    sources=[]
    for s in sections:
        for x in s['sources']:
            if x not in sources: sources.append(x)
    return {'person':person,'title':title,'dek':dek,'sections':sections,'sources':sources}

def assoc(data,item):
    for i,old in enumerate(data['associations']):
        if old['from']==item['from'] and old['to']==item['to']: data['associations'][i]=item; return
    data['associations'].append(item)

